// SPDX-License-Identifier: Apache-2.0
// Regenerates every generated file of @aphrody/m3-tokens from its Rust owner:
//   src/libm3-wasm.ts   crates/libm3-wasm compiled for wasm32-unknown-unknown (runtime dynamic colour)
//   src/m3-tokens.css   aphrody-m3-tokens Sheet::Static through the @aphrody/bun m3Css FFI
//   src/expressive.css  src/expressive.ts
//
//   bun scripts/generate.ts           write the files
//   bun scripts/generate.ts --check   exit 1 when a committed file differs from its source
//   --only src/libm3-wasm.ts           restrict either mode to the named outputs (repeatable)
import { m3Css } from "@aphrody/bun";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, join, relative } from "node:path";
import { expressiveCss } from "../src/expressive.ts";

const packageRoot = join(import.meta.dir, "..");
const repoRoot = join(packageRoot, "..", "..");
const check = process.argv.includes("--check");
const only = process.argv.flatMap((arg, index) => (process.argv[index - 1] === "--only" ? [arg] : []));

/** Build crates/libm3-wasm through the canonical Cargo owner and return the module bytes. */
async function buildWasm(): Promise<Uint8Array> {
  const cargo = [
    "bun",
    join(repoRoot, "scripts/aphrody/build/rust/cargo-serial.ts"),
    ...(process.platform === "win32" ? ["--msvc"] : []),
    "build",
    "--locked",
    "--release",
    "-p",
    "libm3-wasm",
    "--target",
    "wasm32-unknown-unknown",
    "--message-format=json-render-diagnostics",
  ];
  const child = Bun.spawn(cargo, { cwd: repoRoot, stdout: "pipe", stderr: "inherit" });
  const [stdout, code] = await Promise.all([new Response(child.stdout).text(), child.exited]);
  if (code !== 0) throw new Error(`libm3-wasm build failed (exit ${code})`);
  const artifact = stdout
    .split("\n")
    .filter(line => line.startsWith("{"))
    .map(line => JSON.parse(line) as { reason?: string; target?: { name?: string }; filenames?: string[] })
    .filter(message => message.reason === "compiler-artifact" && message.target?.name === "libm3_wasm")
    .flatMap(message => message.filenames ?? [])
    .find(file => file.endsWith(".wasm"));
  if (!artifact) throw new Error("Cargo reported no libm3_wasm.wasm artifact");
  return Bun.file(artifact).bytes();
}

function wasmModule(bytes: Uint8Array): string {
  const sha256 = new Bun.CryptoHasher("sha256").update(bytes).digest("hex");
  const base64 = Buffer.from(bytes).toString("base64");
  const lines = base64.match(/.{1,120}/g) ?? [];
  return [
    "// SPDX-License-Identifier: Apache-2.0",
    "// Generated by packages/m3-tokens/scripts/generate.ts from crates/libm3-wasm - do not hand-edit.",
    "// Regenerate with: bun run --cwd packages/m3-tokens generate",
    `/** SHA-256 of the embedded wasm32-unknown-unknown module (${bytes.length} bytes). */`,
    `export const LIBM3_WASM_SHA256 = "${sha256}";`,
    "",
    "/** The libm3-wasm module, base64-encoded so it instantiates synchronously in every host. */",
    "export const LIBM3_WASM_BASE64 =",
    ...lines.map((line, index) => `  "${line}"${index === lines.length - 1 ? ";" : " +"}`),
    "",
  ].join("\n");
}

const outputs: Record<string, () => Promise<string> | string> = {
  "src/libm3-wasm.ts": async () => wasmModule(await buildWasm()),
  "src/m3-tokens.css": () => m3Css({ sheet: "static" }),
  "src/expressive.css": () => expressiveCss(),
};

/** The text the repo formatter (bun-format.json) makes of `text` saved as `path`; committed files are formatted. */
async function formatted(path: string, text: string): Promise<string> {
  const dir = await mkdtemp(join(tmpdir(), "m3-tokens-"));
  try {
    const file = join(dir, basename(path));
    await Bun.write(file, text);
    const child = Bun.spawn(["bun", "fmt", "--config", join(repoRoot, "bun-format.json"), file], {
      cwd: repoRoot,
      stdout: "pipe",
      stderr: "pipe",
    });
    const [out, err, code] = await Promise.all([
      new Response(child.stdout).text(),
      new Response(child.stderr).text(),
      child.exited,
    ]);
    if (code !== 0) throw new Error(`bun fmt failed on ${path}: ${err || out}`);
    return await Bun.file(file).text();
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

let stale = 0;
for (const path of only) if (!Object.hasOwn(outputs, path)) throw new Error(`Unknown generated output ${path}`);
for (const [path, render] of Object.entries(outputs)) {
  if (only.length && !only.includes(path)) continue;
  const file = join(packageRoot, path);
  const expected = await formatted(path, await render());
  const current = (await Bun.file(file).exists()) ? await Bun.file(file).text() : undefined;
  const name = relative(repoRoot, file).replaceAll("\\", "/");
  if (current === expected) {
    console.log(`fresh  ${name}`);
  } else if (check) {
    console.error(`stale  ${name}`);
    stale++;
  } else {
    await Bun.write(file, expected);
    console.log(`wrote  ${name}`);
  }
}
if (stale) {
  console.error(`${stale} generated file(s) differ from their source: bun run --cwd packages/m3-tokens generate`);
  process.exit(1);
}
